#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

int valid(const char *s) {
    if (strlen(s) != 8) return 0;
    if (!isupper((unsigned char)s[0])) return 0;
    if (!isupper((unsigned char)s[1]) && s[1] != ' ') return 0;
    if (!isdigit((unsigned char)s[2]) || !isdigit((unsigned char)s[3])) return 0;
    if (!isdigit((unsigned char)s[4]) && s[4] != ' ') return 0;
    for (int i = 5; i < 8; i++)
        if (!isupper((unsigned char)s[i])) return 0;
    return 1;
}

int main(void) {
    char line[64];
    int n;
    if (!fgets(line, sizeof line, stdin)) return 0;
    n = atoi(line);
    for (int k = 0; k < n; k++) {
        if (!fgets(line, sizeof line, stdin)) line[0] = '\0';
        line[strcspn(line, "\r\n")] = '\0';
        puts(valid(line) ? "DA" : "NU");
    }
    return 0;
}

description:
Starea fiecărei curse Uber e codificată pe un octet:
- bitul 0: cursa a fost anulată (1) sau nu (0);
- bitul 1: cursa e în desfășurare (1) sau nu (0);
- biții 2–4: numărul de stele, între 0 și 5.

Ratingul unui șofer este suma stelelor curselor încheiate împărțită la numărul lor (o cursă încheiată nu e nici anulată, nici în desfășurare). Un șofer fără curse încheiate are ratingul 0.

Afișează numele șoferului cu ratingul cel mai mare și ratingul lui cu două zecimale. La egalitate câștigă primul în ordinea citirii.

