#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    unsigned long long ts;
    char dest[256];
    char *text;
} TMesaj;

int cmp(const void *a, const void *b) {
    const TMesaj *x = (const TMesaj *)a, *y = (const TMesaj *)b;
    int c = strcmp(x->dest, y->dest);
    if (c) return c;
    return (x->ts > y->ts) - (x->ts < y->ts);
}

int main(void) {
    int n;
    char buf[1024];
    if (scanf("%d", &n) != 1) return 0;
    TMesaj *m = (TMesaj *)malloc(n * sizeof(TMesaj));
    for (int i = 0; i < n; i++) {
        scanf("%llu %255s %1023s", &m[i].ts, m[i].dest, buf);
        m[i].text = (char *)malloc(strlen(buf) + 1);
        strcpy(m[i].text, buf);
    }
    qsort(m, n, sizeof(TMesaj), cmp);
    for (int i = 0; i < n; i++) {
        printf("%s %llu %s\n", m[i].dest, m[i].ts, m[i].text);
        free(m[i].text);
    }
    free(m);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char nume[21];
    double x, y, d;
} TSofer;

int cmp(const void *a, const void *b) {
    const TSofer *p = (const TSofer *)a, *q = (const TSofer *)b;
    if (p->d < q->d) return -1;
    if (p->d > q->d) return 1;
    return strcmp(p->nume, q->nume);
}

int main(void) {
    int n, nr;
    double px, py;
    if (scanf("%d %d", &n, &nr) != 2) return 0;
    TSofer *s = (TSofer *)malloc(n * sizeof(TSofer));
    for (int i = 0; i < n; i++) scanf("%20s %lf %lf", s[i].nume, &s[i].x, &s[i].y);
    scanf("%lf %lf", &px, &py);
    for (int i = 0; i < n; i++)
        s[i].d = (s[i].x - px) * (s[i].x - px) + (s[i].y - py) * (s[i].y - py);
    qsort(s, n, sizeof(TSofer), cmp);
    for (int i = 0; i < nr; i++) puts(s[i].nume);
    free(s);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef unsigned long long ull;
typedef ull *(*Generator)(unsigned r, unsigned a, unsigned n);

static int prim(ull x) {
    if (x < 2) return 0;
    for (ull d = 2; d * d <= x; d++)
        if (x % d == 0) return 0;
    return 1;
}

ull *prime(unsigned r, unsigned a, unsigned n) {
    ull *v = (ull *)malloc(n * sizeof(ull));
    ull x = 1;
    for (unsigned i = 0; i < n; i++) {
        do x++; while (!prim(x));
        v[i] = x;
    }
    return v;
}

ull *fibo(unsigned r, unsigned a, unsigned n) {
    ull *v = (ull *)malloc(n * sizeof(ull));
    for (unsigned i = 0; i < n; i++) v[i] = i < 2 ? 1 : v[i - 1] + v[i - 2];
    return v;
}

ull *arit(unsigned r, unsigned a, unsigned n) {
    ull *v = (ull *)malloc(n * sizeof(ull));
    for (unsigned i = 0; i < n; i++) v[i] = i == 0 ? a : v[i - 1] + r;
    return v;
}

ull *geom(unsigned r, unsigned a, unsigned n) {
    ull *v = (ull *)malloc(n * sizeof(ull));
    for (unsigned i = 0; i < n; i++) v[i] = i == 0 ? a : v[i - 1] * r;
    return v;
}

int main(void) {
    Generator gen[4] = {prime, fibo, arit, geom};
    unsigned t, n, r = 0, a = 0;
    if (scanf("%u %u", &t, &n) != 2) return 0;
    if (t >= 2) scanf("%u %u", &r, &a);
    ull *v = gen[t](r, a, n);
    for (unsigned i = 0; i < n; i++) printf("%llu%c", v[i], i + 1 < n ? ' ' : '\n');
    free(v);
    return 0;
}

