#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char tip, culoare;
    int lin, col;
} TPiesa;

int main(void) {
    int n, p;
    if (scanf("%d %d", &n, &p) != 2) return 0;
    char *tabla = (char *)calloc((n + 2) * (n + 2), 1);
    TPiesa *v = (TPiesa *)malloc(p * sizeof(TPiesa));
    for (int i = 0; i < p; i++) {
        scanf(" %c %c %d %d", &v[i].tip, &v[i].culoare, &v[i].lin, &v[i].col);
        tabla[v[i].lin * (n + 2) + v[i].col] = v[i].culoare;
    }
    int dl[4] = {-1, 1, 0, 0}, dc[4] = {0, 0, -1, 1};
    for (int i = 0; i < p; i++) {
        if (v[i].tip != 'T') continue;
        int cnt = 0;
        for (int d = 0; d < 4; d++) {
            int l = v[i].lin + dl[d], c = v[i].col + dc[d];
            while (l >= 1 && l <= n && c >= 1 && c <= n) {
                char cul = tabla[l * (n + 2) + c];
                if (cul) {
                    if (cul != v[i].culoare) cnt++;
                    break;
                }
                cnt++;
                l += dl[d];
                c += dc[d];
            }
        }
        printf("%d\n", cnt);
    }
    free(tabla);
    free(v);
    return 0;
}
